// Hash-aware update helper for the mem-plus installer.
//
// NSIS has no SHA-256 and no way to hash 2,500 payload files without spawning
// certutil once per file. The installer already requires Node (npm is used for
// dependencies), so this helper is the small piece that compares the installed
// tree with the payload hashes generated by build.ps1.
//
// It does NOT copy the payload. It only deletes:
//   * files whose current SHA-256 differs from the new payload (so NSIS's
//     `SetOverwrite off` pass rewrites them),
//   * files the previous install recorded that this payload no longer contains,
//   * directories the previous install recorded that are now empty and gone.
// Files whose hash already matches are left untouched, which is what makes
// an update stop deleting and rewriting the whole 2,500-file tree.
//
// A missing or malformed helper is not fatal: installer.nsi falls back to the
// old full-replace path when this exits non-zero.

import { createHash } from "node:crypto";
import { chmod, lstat, mkdir, readFile, rm, rmdir } from "node:fs/promises";
import path from "node:path";

function fail(message) {
  throw new Error(message);
}

function argument(name) {
  const index = process.argv.indexOf(name);
  if (index < 0) return undefined;
  const value = process.argv[index + 1];
  if (value === undefined || value.startsWith("--")) fail(`${name} needs a value`);
  return value;
}

function manifestLines(text) {
  return text
    .split(/\r?\n/)
    .map((line) => line.replace(/\r$/, ""))
    .filter((line) => line.length > 0);
}

async function readManifest(file) {
  try {
    return manifestLines(await readFile(file, "utf8"));
  } catch (error) {
    if (error.code === "ENOENT") return [];
    throw error;
  }
}

// Every path in a manifest is relative to the install root. Reject anything
// that could escape it before it reaches delete/rmdir. Build.ps1 only writes
// relative payload paths, but the previous install's manifest is a file on
// disk and is therefore treated as untrusted input here.
function normalizeRelative(input) {
  if (input.includes("\0")) fail("manifest path contains NUL");
  let value = input.replace(/\\/g, "/");
  if (value.startsWith("./")) value = value.slice(2);
  if (!value || path.posix.isAbsolute(value) || /^[A-Za-z]:/.test(value)) {
    fail(`manifest path is not relative: ${JSON.stringify(input)}`);
  }
  const parts = value.split("/");
  if (parts.some((part) => part === ".." || part === "")) {
    fail(`manifest path is not a clean relative path: ${JSON.stringify(input)}`);
  }
  return parts.join("/");
}

function resolveInside(root, relative) {
  const absolute = path.resolve(root, ...relative.split("/"));
  const checked = path.relative(root, absolute);
  if (!checked || checked.startsWith("..") || path.isAbsolute(checked)) {
    fail(`manifest path escapes install root: ${relative}`);
  }
  return absolute;
}

async function lstatOrNull(file) {
  try {
    return await lstat(file);
  } catch (error) {
    if (error.code === "ENOENT") return null;
    throw error;
  }
}

async function sha256(file) {
  const data = await readFile(file);
  return createHash("sha256").update(data).digest("hex");
}

async function removeFile(file) {
  try {
    await rm(file, { force: true });
  } catch (error) {
    if (error.code !== "EPERM" && error.code !== "EACCES") throw error;
    // A read-only attribute is the usual cause on Windows. Clear it and retry
    // once; a genuinely locked file still fails and the installer falls back.
    await chmod(file, 0o666).catch(() => {});
    await rm(file, { force: true });
  }
  if (await lstatOrNull(file)) fail(`could not remove ${file}`);
}

function depth(relative) {
  return relative.split("/").length;
}

async function main() {
  const targetArg = argument("--target");
  const hashesFile = argument("--hashes");
  const newDirsFile = argument("--new-dirs");
  if (!targetArg || !hashesFile) {
    fail("usage: sync-payload.mjs --target <dir> --hashes <file> [--new-dirs <file>]");
  }

  const target = path.resolve(targetArg);
  await mkdir(target, { recursive: true });

  const newFiles = new Map();
  for (const line of await readManifest(hashesFile)) {
    const separator = line.indexOf("|");
    if (separator < 1) fail(`malformed hash line: ${JSON.stringify(line)}`);
    const relative = normalizeRelative(line.slice(0, separator));
    const hash = line.slice(separator + 1).trim().toLowerCase();
    if (!/^[0-9a-f]{64}$/.test(hash)) {
      fail(`malformed SHA-256 for ${relative}`);
    }
    newFiles.set(relative, hash);
  }
  if (newFiles.size === 0) fail("hash manifest is empty");

  const newDirs = new Set();
  if (newDirsFile) {
    for (const line of await readManifest(newDirsFile)) {
      newDirs.add(normalizeRelative(line));
    }
  } else {
    for (const relative of newFiles.keys()) {
      const parts = relative.split("/");
      parts.pop();
      while (parts.length > 0) {
        newDirs.add(parts.join("/"));
        parts.pop();
      }
    }
  }

  const oldFiles = new Set();
  for (const line of await readManifest(path.join(target, ".mem-plus-payload-files.txt"))) {
    // Tolerate a future path|hash manifest; the current one is path-only.
    const raw = line.includes("|") ? line.slice(0, line.indexOf("|")) : line;
    try {
      oldFiles.add(normalizeRelative(raw));
    } catch (error) {
      console.error(`mem-plus update: ignoring bad old file entry (${error.message})`);
    }
  }

  const oldDirs = new Set();
  for (const line of await readManifest(path.join(target, ".mem-plus-payload-dirs.txt"))) {
    try {
      oldDirs.add(normalizeRelative(line));
    } catch (error) {
      console.error(`mem-plus update: ignoring bad old dir entry (${error.message})`);
    }
  }

  let unchanged = 0;
  let rewrite = 0;
  let missing = 0;
  let removed = 0;

  // Delete files this payload no longer ships before making directories: a
  // file in the old tree can legitimately become a directory in the new one.
  for (const relative of oldFiles) {
    if (newFiles.has(relative)) continue;
    const absolute = resolveInside(target, relative);
    const stat = await lstatOrNull(absolute);
    if (!stat) continue;
    if (stat.isDirectory()) {
      console.error(`mem-plus update: old manifest names a directory, leaving it: ${relative}`);
      continue;
    }
    await removeFile(absolute);
    removed += 1;
  }

  // New directories must exist before NSIS's File pass; File creates parents
  // for written files, but an empty payload directory would otherwise vanish.
  for (const relative of [...newDirs].sort((a, b) => depth(a) - depth(b))) {
    const absolute = resolveInside(target, relative);
    const stat = await lstatOrNull(absolute);
    if (stat && !stat.isDirectory()) {
      // A stale owned file at this path; the extra pass above normally removed
      // it already, but a user file is never silently replaced by a directory.
      if (!oldFiles.has(relative)) {
        fail(`a file is blocking new directory ${relative}`);
      }
      await removeFile(absolute);
    }
    await mkdir(absolute, { recursive: true });
  }

  // Compare every new file with what is on disk. Identical files are left in
  // place; File /r with SetOverwrite off will then skip them.
  for (const [relative, expected] of newFiles) {
    const absolute = resolveInside(target, relative);
    const stat = await lstatOrNull(absolute);
    if (!stat) {
      missing += 1;
      continue;
    }
    if (stat.isDirectory()) {
      // A file in this payload cannot be written while a directory owns the
      // name. Only remove it when it is an old owned directory and empty.
      if (!oldDirs.has(relative)) fail(`a directory is blocking new file ${relative}`);
      try {
        await rmdir(absolute);
      } catch (error) {
        if (error.code !== "ENOENT" && error.code !== "ENOTEMPTY") throw error;
        if (error.code === "ENOTEMPTY") fail(`a non-empty directory is blocking new file ${relative}`);
      }
      missing += 1;
      continue;
    }
    const actual = await sha256(absolute);
    if (actual === expected) {
      unchanged += 1;
      continue;
    }
    await removeFile(absolute);
    rewrite += 1;
  }

  // Deepest first (the generated list is already in that order, but sort so a
  // hand-edited manifest cannot leave a parent before its child). rmdir with no
  // recursion is the safety property: anything still inside is not ours.
  let dirsRemoved = 0;
  for (const relative of [...oldDirs].sort((a, b) => depth(b) - depth(a))) {
    if (newDirs.has(relative)) continue;
    const absolute = resolveInside(target, relative);
    try {
      await rmdir(absolute);
      dirsRemoved += 1;
    } catch (error) {
      if (error.code !== "ENOENT" && error.code !== "ENOTEMPTY" && error.code !== "EACCES") {
        throw error;
      }
    }
  }

  console.log(
    `mem-plus update: unchanged=${unchanged} rewritten=${rewrite} missing=${missing} removed=${removed} dirs_removed=${dirsRemoved}`,
  );
}

try {
  await main();
} catch (error) {
  console.error(`mem-plus update: ERROR ${error.message}`);
  process.exitCode = 1;
}
